     1	package org.springframework.samples.petclinic.rest.function.owner;
     2	
     3	import net.officefloor.plugin.variable.Val;
     4	import org.springframework.samples.petclinic.model.Owner;
     5	import org.springframework.samples.petclinic.repository.OwnerRepository;
     6	
     7	/**
     8	 * Assigns the owner's {@code customerCode} as {@code <CITY3>-<LAST3>-<NNNN>}: the upper-cased first
     9	 * three letters of the city and last name, and a per-city 4-digit sequence one more than the owners
    10	 * already in that city. Runs before the owner is saved, so the sequence excludes the owner being
    11	 * created.
    12	 */
    13	public class AssignCustomerCode {
    14	
    15	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
    16	        String city3 = three(owner.getCity());
    17	        String last3 = three(owner.getLastName());
    18	        long inCity = ownerRepository.findAll().stream()
    19	            .filter(o -> owner.getCity().equalsIgnoreCase(o.getCity())).count();
    20	        owner.setCustomerCode(String.format("%s-%s-%04d", city3, last3, inCity + 1));
    21	    }
    22	
    23	    private static String three(String value) {
    24	        return value.substring(0, Math.min(3, value.length())).toUpperCase();
    25	    }
    26	}

