     1	package org.springframework.samples.petclinic.rest.function.owner;
     2	
     3	/**
     4	 * Single source of truth for an owner's {@code checkDigit}: the Luhn check digit (0-9) computed
     5	 * over the digits contained in the {@code customerCode}. Non-digit characters are ignored.
     6	 */
     7	public final class CustomerCodeCheckDigit {
     8	
     9	    private CustomerCodeCheckDigit() {
    10	    }
    11	
    12	    public static int of(String customerCode) {
    13	        int sum = 0;
    14	        boolean doubling = true;
    15	        for (int i = customerCode.length() - 1; i >= 0; i--) {
    16	            char c = customerCode.charAt(i);
    17	            if (c < '0' || c > '9') {
    18	                continue;
    19	            }
    20	            int d = c - '0';
    21	            if (doubling && (d *= 2) > 9) {
    22	                d -= 9;
    23	            }
    24	            sum += d;
    25	            doubling = !doubling;
    26	        }
    27	        return (10 - (sum % 10)) % 10;
    28	    }
    29	}

