     1	package org.springframework.samples.petclinic.rest.function.owner;
     2	
     3	import java.util.Map;
     4	
     5	import org.springframework.samples.petclinic.model.Owner;
     6	
     7	/**
     8	 * Single source of truth for an owner's derived {@code locality} (region code). Resolution prefers
     9	 * the postcode: a 4-digit postcode in a known range maps to its region (NSW 2000-2099, VIC
    10	 * 3000-3099, QLD 4000-4099). When the postcode is absent or in no known range, it falls back to the
    11	 * city-to-region table (Sydney/NSW, Melbourne/VIC, Brisbane/QLD). Anything unresolved is
    12	 * {@code "UNKNOWN"}. Preferring the postcode disambiguates cities that share a name.
    13	 */
    14	public final class OwnerLocality {
    15	
    16	    private static final Map<String, String> CITY_REGION = Map.of(
    17	            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
    18	
    19	    private OwnerLocality() {
    20	    }
    21	
    22	    public static String region(Owner owner) {
    23	        String byPostcode = byPostcode(owner.getPostcode());
    24	        if (byPostcode != null) {
    25	            return byPostcode;
    26	        }
    27	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
    28	    }
    29	
    30	    private static String byPostcode(String postcode) {
    31	        if (postcode == null) {
    32	            return null;
    33	        }
    34	        int value = Integer.parseInt(postcode);
    35	        if (value >= 2000 && value <= 2099) {
    36	            return "NSW";
    37	        }
    38	        if (value >= 3000 && value <= 3099) {
    39	            return "VIC";
    40	        }
    41	        if (value >= 4000 && value <= 4099) {
    42	            return "QLD";
    43	        }
    44	        return null;
    45	    }
    46	}

########## src/main/java/org/springframework/samples/petclinic/rest/function/owner/ValidatePostcode.java ##########
     1	package org.springframework.samples.petclinic.rest.function.owner;
     2	
     3	import java.util.Map;
     4	
     5	import net.officefloor.plugin.variable.Val;
     6	import org.springframework.samples.petclinic.model.Owner;
     7	import org.springframework.samples.petclinic.rest.escalation.InvalidPostcodeException;
     8	
     9	/**
    10	 * When an owner supplies a postcode, rejects it when it falls outside the inclusive range for the
    11	 * city's region (Sydney/NSW 2000-2099, Melbourne/VIC 3000-3099, Brisbane/QLD 4000-4099). A city
    12	 * with no known region accepts any 4-digit postcode, and an absent postcode is always accepted.
    13	 * The 4-digit shape is already enforced by the request DTO, so a present postcode parses cleanly.
    14	 */
    15	public class ValidatePostcode {
    16	
    17	    private static final Map<String, int[]> REGION_RANGES = Map.of(
    18	            "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
    19	
    20	    private static final Map<String, String> CITY_REGION = Map.of(
    21	            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
    22	
    23	    public void service(@Val Owner owner) throws InvalidPostcodeException {
    24	        String postcode = owner.getPostcode();
    25	        if (postcode == null) {
    26	            return;
    27	        }
    28	        String region = CITY_REGION.get(owner.getCity());
    29	        if (region == null) {
    30	            return;
    31	        }
    32	        int[] range = REGION_RANGES.get(region);
    33	        int value = Integer.parseInt(postcode);
    34	        if (value < range[0] || value > range[1]) {
    35	            throw new InvalidPostcodeException(owner.getCity(), postcode);
    36	        }
    37	    }
    38	}

