     1	package org.springframework.samples.petclinic.rest.function.owner;
     2	
     3	import java.time.DayOfWeek;
     4	import java.time.LocalDate;
     5	
     6	/**
     7	 * Rolls a registration date forward onto a business day: a Saturday or Sunday becomes the next
     8	 * Monday, any weekday is left unchanged. Applied to the effective registration date (supplied or
     9	 * defaulted) so every value derived from it — the membership number's year, the daily create-limit
    10	 * bucket — sees the same adjusted day.
    11	 */
    12	public final class BusinessDay {
    13	
    14	    private BusinessDay() {
    15	    }
    16	
    17	    public static LocalDate roll(LocalDate date) {
    18	        if (date.getDayOfWeek() == DayOfWeek.SATURDAY) {
    19	            return date.plusDays(2);
    20	        }
    21	        if (date.getDayOfWeek() == DayOfWeek.SUNDAY) {
    22	            return date.plusDays(1);
    23	        }
    24	        return date;
    25	    }
    26	}

