    15	    public void service(@Valid @RequestBody OwnerFieldsDto request, OwnerMapper ownerMapper, Out<Owner> built,
    16	            Out<Boolean> sharesHousehold) throws InvalidTelephoneException {
    17	        Owner owner = ownerMapper.toOwner(request);
    18	        owner.setAddress(AddressNormalizer.normalize(owner.getAddress()));
    19	        owner.setTelephone(toE164(owner.getTelephone()));
    20	        java.time.LocalDate effective = owner.getRegistrationDate() == null
    21	                ? java.time.LocalDate.now() : owner.getRegistrationDate();
    22	        owner.setRegistrationDate(BusinessDay.roll(effective));
    23	        sharesHousehold.set(Boolean.TRUE.equals(request.getSharesHousehold()));
