    26	
    27	    /**
    28	     * Normalizes a telephone to E.164: strip spaces, dashes and brackets; keep a leading '+' with its
    29	     * country code, otherwise assume '+61' and drop a single leading '0' from the national digits.
    30	     * Requires 8 to 15 digits after the '+'.
    31	     */
    32	    private static String toE164(String raw) throws InvalidTelephoneException {
    33	        String cleaned = (raw == null ? "" : raw).replaceAll("[\\s\\-()\\[\\]]", "");
    34	        String digits;
    35	        if (cleaned.startsWith("+")) {
    36	            digits = cleaned.substring(1);
    37	        } else {
    38	            digits = "61" + (cleaned.startsWith("0") ? cleaned.substring(1) : cleaned);
    39	        }
    40	        if (!digits.matches("\\d{8,15}") || !hasValidNationalLength(digits)) {
    41	            throw new InvalidTelephoneException(raw);
    42	        }
    43	        return "+" + digits;
    44	    }
    45	
    46	    /**
    47	     * Checks the national-number length for the recognised country codes: '+61' requires 9 national
    48	     * digits and '+1' requires 10. Other country codes have no per-country rule here.
    49	     */
    50	    private static boolean hasValidNationalLength(String digits) {
    51	        if (digits.startsWith("61")) {
    52	            return digits.length() - 2 == 9;
    53	        }
    54	        if (digits.startsWith("1")) {
    55	            return digits.length() - 1 == 10;
    56	        }
    57	        return true;
    58	    }
    59	}

